{"command": "python3 - <<'EOF'
import socket, struct, random

def dns_query(server, name, qtype=12):
    tid = random.randint(0, 0xFFFF)
    header = struct.pack(">HHHHHH", tid, 0x0100, 1, 0, 0, 0)
    qname = b""
    for part in name.rstrip(".").split("."):
        qname += bytes([len(part)]) + part.encode()
    qname += b"\x00"
    question = qname + struct.pack(">HH", qtype, 1)
    s = socket.socket(socket.AF_INET, socket.SOCK_DGRAM)
    s.settimeout(2)
    s.sendto(header + question, (server, 53))
    try:
        data, _ = s.recvfrom(4096)
    except socket.timeout:
        return None
    return data

def parse_ptr(data):
    an = struct.unpack(">H", data[6:8])[0]
    i = 12
    while data[i] != 0:
        i += data[i] + 1
    i += 5
    out = []
    for _ in range(an):
        while True:
            b = data[i]
            if b & 0xC0 == 0xC0:
                i += 2; break
            elif b == 0:
                i += 1; break
            else:
                i += b + 1
        rtype, rclass, ttl, rdlen = struct.unpack(">HHIH", data[i:i+10])
        i += 10
        rdata = data[i:i+rdlen]
        i += rdlen
        if rtype == 12:
            # decode name
            j = 0; labels = []
            while rdata[j] != 0:
                if rdata[j] & 0xC0 == 0xC0:
                    ptr = ((rdata[j] & 0x3F) << 8) | rdata[j+1]
                    # chase pointer in full data
                    k = ptr
                    while data[k] != 0:
                        labels.append(data[k+1:k+1+data[k]].decode())
                        k += 1 + data[k]
                    j += 2
                    break
                labels.append(rdata[j+1:j+1+rdata[j]].decode())
                j += 1 + rdata[j]
            out.append(".".join(labels))
    return out

for i in range(1, 21):
    name = f"{i}.0.24.172.in-addr.arpa"
    d = dns_query("127.0.0.11", name)
    if d:
        names = parse_ptr(d)
        if names:
            print(f"172.24.0.{i} -> {names}")
EOF"}

